const $=id=>document.getElementById(id),E=Expedition;
const definitions={forest:['Forest','Woodland'],camp:['Camp','Supplies here'],bridge:['Bridge','Water crossing'],mountain:['Mountain','Needs rope'],ruin:['Ruins','Ancient walls'],beacon:['Beacon','Guiding light'],marsh:['Marsh','Do not enter'],cave:['Cave','Needs lantern'],lagoon:['Lagoon','Needs boat']};
const glyphPaths=['<path d="M12 2l9 10-9 10L3 12z"/>','<circle cx="7" cy="7" r="3"/><circle cx="17" cy="7" r="3"/><circle cx="12" cy="17" r="3"/>','<path d="M3 18L8 5l5 13 5-13 3 13"/>','<path d="M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>','<path d="M4 6h16M4 12h16M4 18h16"/>','<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/>','<path d="M3 20V4h6v8h6V4h6v16"/>','<path d="M17 3a10 10 0 1 0 0 18 8 8 0 0 1 0-18z"/>','<path d="M4 4h16v16H4zM4 12h16M12 4v16"/>'];
