function begin(){const m=mission();animation=null;state.mode=m.kind==='route'?'planning':'playing';state.plan=[];state.visited=[];state.gear=[];state.current=m.start||null;state.attemptMistakes=0;feedback(m.kind==='route'?`Plan ${m.length} connected stops. You can undo before walking. The small camp badges show their supplies.`:'Use the key to decode the destination, then check both conditions.');$('island-reward').hidden=true;render();}
function choose(id){if(state.mode==='playing'){const m=mission();if(m.solutions.includes(id)){state.current=id;state.visited=[id];discover(id);complete();}else{state.mistakes++;state.attemptMistakes++;beep(false);feedback(E.get(map,id).type!==m.type?'That marker’s meaning does not match the destination symbol. Check the key.':'The symbol matches, but at least one position or connection condition does not. Check both references.','error');}updateMarkers();draw();}else if(state.mode==='planning'){const m=mission(),last=state.plan.at(-1)||m.start;if(state.plan.length>=m.length){feedback('Your plan is full. Remove a stop or walk the route.');return;}if(!E.neighbors(map,last).includes(id)){feedback('Plan one connected path at a time. This marker is not beside your last planned stop.','error');return;}if(state.plan.includes(id)||id===m.start){feedback('This expedition cannot revisit a stop. Undo to change your route.');return;}state.plan.push(id);feedback(state.plan.length===m.length?'The plan is ready. Walk it to test your map reading.':`${state.plan.length} stops planned. Keep following the symbols.`);render();}}
function discover(id){if(!state.discovered.includes(id))state.discovered.push(id);const gear=E.get(map,id).gear;if(gear&&!state.gear.includes(gear))state.gear.push(gear);}
function walk(){if(state.mode!=='planning')return;const m=mission();if(state.plan.length!==m.length)return;state.plans++;const result=E.verdict(map,m,state.plan);state.mode='walking';state.current=m.start;state.visited=[];state.gear=[];animation={elapsed:0,index:0,result};feedback('Your explorer is testing the expedition…');render();}
function tick(ms){state.t+=ms;if(animation){animation.elapsed+=ms;while(animation&&animation.elapsed>=650){animation.elapsed-=650;const {index,result}=animation;if(!result.ok&&index>=result.at){animation=null;state.mode='planning';state.mistakes++;state.attemptMistakes++;state.current=mission().start;state.visited=[];state.gear=[];state.plan=[];beep(false);feedback(result.why+' Revise your whole route and try again.','error');render();break;}const id=state.plan[index];state.current=id;state.visited.push(id);discover(id);animation.index++;if(animation.index>=state.plan.length){animation=null;complete();}else{feedback(`Stop ${index+1} reached.${state.gear.length?' Packed: '+state.gear.join(', ')+'.':''}`);render();}}}draw();}
function complete(){state.mode='complete';if(state.attemptMistakes===0)state.perfect++;if(state.optional===null)state.completed[state.island]=Math.max(state.completed[state.island],state.mission+1);else if(!state.relics[state.island].includes(state.optional))state.relics[state.island].push(state.optional);save();beep();feedback(state.optional!==null?'Hidden relic recovered! Optional hunts reward careful route planning.':state.mission===4?'The island treasure is yours! Three optional relics are still hidden.':'Map piece recovered. Your next challenge is waiting.','success');render();}
function summary(){state.mode='island-complete';animation=null;updateMarkers();totals();islandBar();$('island-reward').hidden=false;$('island-reward').innerHTML=`<div class="reward-card"><span class="eyebrow">ISLAND TREASURE RECOVERED</span><h2>${map.name} complete!</h2><p>Five map pieces collected. Try a harder relic hunt, or sail onward.</p><div class="relic-list">${map.relics.map((m,i)=>`<button data-relic="${i}" class="secondary" ${state.relics[state.island].includes(i)?'disabled':''}>${state.relics[state.island].includes(i)?'✓':'✦'} ${m.title}</button>`).join('')}</div><button id="sail" class="primary">${state.island<2?'Sail to '+maps[state.island+1].name+' →':'Complete the expedition →'}</button><small>You can return to unlocked islands for missed relics.</small></div>`;$('island-reward').querySelectorAll('[data-relic]').forEach(b=>b.onclick=()=>{state.optional=Number(b.dataset.relic);begin();});$('sail').onclick=()=>{if(state.island<2)switchIsland(state.island+1);else win();};}
function switchIsland(i){if(i>0&&state.completed[i-1]<5)return;state.island=i;map=maps[i];state.discovered=[];state.optional=null;state.mission=Math.min(state.completed[i],4);asset();makeLegend();markers();if(state.completed[i]===5){render();summary();}else begin();save();}
function start(fresh=false){if(fresh){crypto.getRandomValues((seed=new Uint32Array(1)));seed=seed[0];maps=[0,1,2].map(i=>E.campaign(seed,i));state.completed=[0,0,0];state.relics=[[],[],[]];state.island=0;state.mistakes=state.hints=state.plans=state.perfect=0;}state.mode='playing';$('start-screen').style.display='none';$('win-dialog').close();switchIsland(state.island);}
function next(){if(state.mode!=='complete')return;if(state.optional!==null||state.mission===4){state.optional=null;summary();}else{state.mission++;begin();}}
function hint(){if(!['playing','planning'].includes(state.mode))return;state.hints++;feedback(mission().hint);}
function win(){state.mode='won';$('island-reward').hidden=true;const relics=state.relics.flat().length;$('win-dialog').querySelector('h2').innerHTML='Three islands.<br>One brilliant explorer.';$('win-dialog').querySelector('p').textContent=`All 15 map pieces recovered. ${relics}/9 optional relics found. Return to any unlocked island to complete your collection.`;$('win-stats').innerHTML=`<div><strong>${state.perfect}</strong><small>Accurate discoveries</small></div><div><strong>${relics}/9</strong><small>Relics</small></div><div><strong>${state.plans}</strong><small>Routes walked</small></div>`;$('badges')?.remove();const badges=document.createElement('div');badges.id='badges';badges.innerHTML='<span class="earned-badge">🧭 Navigator</span>'+(state.perfect>=12?'<span class="earned-badge">✦ Careful cartographer</span>':'')+(relics===9?'<span class="earned-badge">♛ Relic collector</span>':'');$('win-stats').after(badges);$('win-dialog').showModal();}
function draw(){const {width:w,height:h}=canvas.getBoundingClientRect();ctx.clearRect(0,0,w,h);ctx.fillStyle='#cbe9ee';ctx.fillRect(0,0,w,h);if(image.complete&&image.naturalWidth)ctx.drawImage(image,0,0,w,h);if(state.mode==='ready')return;const planned=[mission().start,...state.plan];map.links.forEach(([a,b])=>{const n=E.get(map,a),q=E.get(map,b),on=planned.some((x,i)=>i<planned.length-1&&((x===a&&planned[i+1]===b)||(x===b&&planned[i+1]===a)));ctx.beginPath();ctx.moveTo(n.x*w/100,n.y*h/100);ctx.lineTo(q.x*w/100,q.y*h/100);ctx.setLineDash(on?[]:[2,7]);ctx.lineCap='round';ctx.lineWidth=5;ctx.strokeStyle='#33553b65';ctx.stroke();ctx.lineWidth=on?3:2;ctx.strokeStyle=on?'#ffd66e':'#fff6db';ctx.stroke();});ctx.setLineDash([]);if(landmarks.complete&&landmarks.naturalWidth){state.discovered.forEach(id=>{const n=E.get(map,id),index=['forest','camp','bridge','mountain','ruin','beacon'].indexOf(n.type);if(index<0)return;const cw=landmarks.naturalWidth/3,ch=landmarks.naturalHeight/2,s=Math.min(w*.09,72);ctx.drawImage(landmarks,index%3*cw,Math.floor(index/3)*ch,cw,ch,n.x*w/100-s/2,n.y*h/100-s*.9,s,s);});}}
function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=r.width*d;canvas.height=r.height*d;ctx.setTransform(d,0,0,d,0,0);draw();}
$('start-btn').onclick=()=>start();$('next').onclick=next;$('walk').onclick=walk;$('undo').onclick=()=>{state.plan.pop();render();};$('hint').onclick=hint;$('restart').onclick=()=>{$('restart-dialog').showModal();};$('restart-cancel').onclick=()=> $('restart-dialog').close();$('restart-confirm').onclick=()=>{$('restart-dialog').close();start(true);};$('help').onclick=()=> $('help-dialog').showModal();$('close-help').onclick=$('help-done').onclick=()=> $('help-dialog').close();$('replay').onclick=()=>start(true);$('view-island').textContent='Return for relics';$('view-island').onclick=()=>{$('win-dialog').close();summary();};$('sound').onclick=()=>{state.sound=!state.sound;$('sound').textContent=state.sound?'Sound on':'Sound off';beep();};async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{}}$('fullscreen').onclick=fullscreen;document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]'))return;if(e.key.toLowerCase()==='f'){e.preventDefault();fullscreen();}if(['playing','planning'].includes(state.mode)&&e.key.startsWith('Arrow')){e.preventDefault();focused=(focused+(['ArrowLeft','ArrowUp'].includes(e.key)?map.nodes.length-1:1))%map.nodes.length;document.querySelectorAll('.marker').forEach((b,i)=>b.tabIndex=i===focused?0:-1);document.querySelectorAll('.marker')[focused].focus();}});
window.render_game_to_text=()=>JSON.stringify({mode:state.mode,seed,island:state.island+1,name:map.name,mission:state.mission+1,optional:state.optional,pieces:state.completed,relics:state.relics,plan:state.plan,current:state.current,gear:state.gear,mistakes:state.mistakes,feedback:$('feedback').textContent,task:mission(),locations:map.nodes,paths:map.links,key:Object.keys(definitions).map((t,i)=>({meaning:t,glyph:map.glyphs[i]})),coordinateSystem:'Percent coordinates. Origin top-left. East right, north up. Dotted paths define connections.'});window.advanceTime=ms=>tick(ms);asset();makeLegend();markers();totals();islandBar();updateMarkers();new ResizeObserver(resize).observe(canvas);let last=performance.now();function frame(t){tick(Math.min(t-last,100));last=t;requestAnimationFrame(frame);}requestAnimationFrame(frame);

